/**
 * Representative stock photos per speciality / treatment page (generated by `npm run stock`
 * from photos/stock-manifest.json). [0] = page banner, [1] = in-article photo.
 * Licence records (source URL + licence) live in the JSON; nothing about photographers is rendered.
 *
 * Every image handed to <StockImage> uses one normalised shape:
 *   { url(w), widths, alt, width, height, representative }
 */
import data from './pageImages.json';
import { hospitalImage } from './photos.js';

export const pageImages = data || {};

const normalise = (img) => ({ ...img, url: (w) => `/images/stock/${img.file}-${w}.webp`, representative: true });

/** Real Gurudev Hospital photos that fit a page. They are used before any stock photo (badge: "Gurudev Hospital"). */
const OWN_PHOTOS = {
  'emergency-trauma-care': ['casualty-emergency-room', 'emergency-crash-cart'],
  'general-laparoscopic-surgery': ['operation-theatre-c-arm'],
  orthopaedics: ['operation-theatre-c-arm'],
  'fracture-treatment': ['operation-theatre-c-arm'],
  'gynaecology-obstetrics': ['labour-room'],
  'maternity-delivery-care': ['labour-room'],
};

export const getPageImages = (slug) => [
  ...(OWN_PHOTOS[slug] || []).map(hospitalImage).filter(Boolean),
  ...(pageImages[slug] || []).map(normalise),
];

export const imgSrcSet = (img) => img.widths.map((w) => `${img.url(w)} ${w}w`).join(', ');
export const imgMedium = (img) => img.url(img.widths.find((w) => w >= 960) || img.widths.at(-1));
export const imgLargest = (img) => img.url(img.widths.at(-1));
export const stockLargest = imgLargest; // backwards-compatible name

/** Which page's photos a health guide uses (`imageFrom` lets a guide borrow another page's photos so two guides never share one). */
export const guideImageSlug = (g) => g.imageFrom || g.treatment;
